import re
def prose(x):
 if isinstance(x,str):
  x=re.sub(r'(?<=[a-z])(?=\d)', ' ', x)
  x=re.sub(r'(?<=\d)(?=[a-zA-Z])', ' ', x)
  x=re.sub(r'(?<=[,;:])(?=\S)', ' ', x)
  x=re.sub(r'(?<=\d), (?=\d{3}\b)', ',', x)
  x=re.sub(r'([a-z])([A-Zα-ωΑ-Ω])', r'\1 \2', x)
  x=re.sub(r'([a-z])([+−])', r'\1 \2', x)
  x=re.sub(r'([a-z])([\[])', r'\1 \2', x)
  x=x.replace('command(', 'command (')
  x=re.sub(r'(?<=[a-zA-Z])(?=[(])', ' ', x) if False else x
  return x.replace('A2 C','A2C').replace('3 D','3D')
 if isinstance(x,list):return [prose(v) for v in x]
 if isinstance(x,dict):return {k:prose(v) for k,v in x.items()}
 return x
