 for field in ('stem','assumptions'):q[field]=prose(q[field])
 for o in q['options']:o['text']=prose(o['text'])
 for field in ('justification','optionExplanations','steps','simpleExplanation','memoryAid','misconceptions','examTraps'):q['solution'][field]=prose(q['solution'][field])
 if 'conflictResolution' in q:
  for field in ('sourceClaim','basis','method'):q['conflictResolution'][field]=prose(q['conflictResolution'][field])
